def merge(a,b):
    for k,v in b.items():
        if isinstance(v,dict):
            if k not in a or not isinstance(a[k],dict): a[k]={}
            merge(a[k],v)
        else: a[k]=v
for lang,tree in patch.items():
    p=root/f'{lang}.json'; data=json.loads(p.read_text()); merge(data,tree)
    p.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    print(lang,'merged')
